// Armadura: ligera 6+, pesada 5+, completa 4+, sin armadura 7+; escudo y barding -1; piel acorazada -X; mejor valor 2+
let ARM = { none: 7, light: 6, heavy: 5, plate: 4 };
let av = (arm, { shield = 0, barding = 0, hide = 0 } = {}) => Math.max(2, Math.min(7, ARM[arm] - shield - barding - hide));

