// util: construye el perfil completo
function u(o) {
  const t = TROOP[o.tt];
  const d = {
    cat: 'inf', M: 4, WS: 3, BS: 3, S: 3, T: 3, W: 1, I: 3, A: 1, Ld: 7, ward: 0, baseW: 25, baseD: 25, files: 5, min: 1, max: 1,
    melee: null, sr: [], ...o,
  };
  d.Sv = d.Sv ?? av(d.arm || 'none', d.avOpt || {});
  d.us = o.us ?? (o.tt === 'monCreature' || o.tt === 'behemoth' ? d.W : t.us); // monstruos: FU = Heridas iniciales
  d.minRank = t.minRank; d.maxRank = t.maxRank;
  if (d.sr.includes('horde')) d.maxRank = Math.min(d.maxRank + 1, 3);
  return d;
}

