  ct_skybombs: { fac: 'ct', name: 'Bombas de Linterna Celeste', cat: 'x', cost: 15, mundane: true, skyBombs: true, onlyT: ['ct_lanterns', 'ct_lanterns_amb', 'ct_lanterns_hail', 'ct_lanterns_amb_hail'], text: 'Una vez por partida, al terminar de mover a 6" de una unidad enemiga no trabada: Bombardeo (1 pierde 1 Herida; 2 el enemigo pierde 1; 3-4 plantilla de 5"; 5-6 dos de 3"; F5 FP −2).' },
  ct_beichai: { fac: 'ct', name: 'Armadura de Jade de Beichai', cat: 'a', cost: 40, sv: 4, ward: 5, mr: 2, text: 'Armadura completa; salvación especial 5+ contra cualquier herida y Resistencia mágica (−2).' },
