  ct_weijin: { fac: 'ct', name: 'Estandarte de Wei-Jin', cat: 's', cost: 60, bn: true, weijin: true, grant: ['fear'], text: 'La unidad causa Miedo. Los enemigos a 12" sufren −1 Ld en chequeos de Miedo, Pánico y Terror.' },
  ct_icon: { fac: 'ct', name: 'Icono de la Furia Celestial', cat: 's', cost: 45, bn: true, single: true, cmdUse: 'icon', text: 'Un solo uso. En la Fase de Mando, si no está trabado, el portador chequea Ld (sin modificar): si lo supera, hasta tu próximo inicio de turno los enemigos no pueden usar Volar (X).' },
