  tkaj_awakening: { mcOnly: true, hpOnly: true, fac: 'tk', name: 'Báculo del Despertar', cat: 'e', cost: 50, awaken: true, text: 'Solo Sumo Sacerdote: con ¡Álzate! sobre una unidad de infantería o caballería, esta recupera D3 Heridas adicionales.' },
