  collar_shapesh: { fac: 'tk', name: 'Collar de Shapesh', cat: 'e', cost: 25, single: true, text: 'Un solo uso: al perder su última Herida, con 4+ no la pierde y en su lugar muere un modelo amigo en su alcance de mando.' },
  kanopi: { fac: 'tk', name: 'Kanopi de Enkhil', cat: 'x', cost: 30, single: true, text: 'Un solo uso, en la subfase de mando y sin estar trabado: chequeo de Ld (sin modificar); si lo supera, se dispersan todos los hechizos que permanecen en juego (también los amigos).' },
  hieratic_jar: { fac: 'tk', name: 'Vasija Hierática*', cat: 'x', cost: 25, wiz: true, single: true, star: true, text: 'Un solo uso, en la subfase de mando: usa ¡Levantaos! dos veces en vez de una.' },
  scarab_brooch: { fac: 'tk', name: 'Broche del Escarabajo', cat: 'x', cost: 20, wiz: true, text: 'Desde Debajo de las Arenas: la unidad invocada puede colocarse a 18" del Sacerdote Funerario en vez de 12".' },
  hail_doom: { fac: 'wood', name: 'Flecha de la Fatalidad*', cat: 'e', cost: 35, star: true, single: true, hailDoom: true, text: 'Un solo uso (arco asrai): si impacta, plantilla de 3" sobre la unidad: cada modelo cubierto sufre un impacto de F4, FP −1, mágico.' },
  wailing_arrow: { fac: 'wood', name: 'Flecha Gemebunda*', cat: 'e', cost: 20, star: true, single: true, wailing: true, text: 'Un solo uso (arco asrai): la unidad que sufra una herida no salvada chequea Pánico como si hubiera sufrido muchas bajas.' },
  blight_arrows: { fac: 'wood', name: 'Flechas de Plaga*', cat: 'e', cost: 15, star: true, single: true, blightA: true, text: 'Un solo uso (arco asrai): el modelo herido chequea Resistencia al inicio de cada turno; si falla, pierde una Herida sin salvación por armadura ni regeneración.' },
