    let best = null; { const g0 = generalOf(army); if (g0) { const al0 = dmAlign(g0.type, g0.opts || []); best = { khorne: 'k', nurgle: 'n', slaanesh: 's', tzeentch: 't' }[al0] || null; } }
    const T = { k: [['dm_bloodletters', 'dm_fleshhounds'], ['dm_bloodcrushers']], n: [['dm_plaguebearers', 'dm_nurglings'], ['dm_beast', 'dm_plaguedrones']], s: [['dm_daemonettes', 'dm_seekers'], ['dm_fiends', 'dm_hellflayer', 'dm_seekerchariot']], t: [['dm_pinkhorrors', 'dm_bluehorrors', 'dm_brimstone'], ['dm_flamers', 'dm_screamers']] }[best];
