    if (has(['vc_wightking', 'vc_wightlord', 'vc_wightking_steed', 'vc_wightlord_steed'])) move(['vc_graveguard', 'vc_blackknights'], 'special', 'core'); // con Tumularios, 0-1 unidad Básica
