// Ejércitos recomendados de 2.000 puntos: parten del de 1.500 y añaden modelos/unidades hasta llenar el límite respetando la composición
(function build2000() {
  const cost = (a) => a.reduce((t, e) => t + unitCost(e.type, e.models, e.std, e.mus, e.champ, e.items, e.banner, e.arrows, e.mark, e.mix, e.opts), 0);
  const ok = (a) => cost(a) <= 2000 && !armyIssues(a, 2000, 'open').filter((m) => !/Unidades básicas|Unidades b/.test(m)).length;
  for (const f of Object.keys(PRESETS)) {
    const base = PRESETS[f][1500]; if (!base || PRESETS[f][2000]) continue;
    const A = base.map((e) => ({ ...e, items: e.items && [...e.items] }));
    const mx = (e) => UNITS[e.type].max || 99, step = (e) => (UNITS[e.type].cat === 'inf' ? 5 : 1);
    const coreFirst = (e) => (UNITS[e.type].comp === 'core' ? 0 : 1);
    for (let guard = 0; guard < 300; guard++) {
      const c = A.filter((e) => !['char', 'mach'].includes(UNITS[e.type].cat) && e.models + step(e) <= mx(e)).sort((x, y) => coreFirst(x) - coreFirst(y) || x.models / mx(x) - y.models / mx(y));
      let done = false;
      for (const e of c) { const old = e.models; e.models += step(e); if (ok(A)) { done = true; break; } e.models = old; }
      if (!done) break;
    }
    // unidades nuevas de la misma facción (básicas primero) mientras quepan
    const pool = Object.keys(UNITS).filter((k) => UNITS[k].faction === f && !['char', 'mach'].includes(UNITS[k].cat) && ['core', 'special'].includes(UNITS[k].comp) && !UNITS[k].merc);
    for (let k = 0; k < 8 && 2000 - cost(A) > 40; k++) {
      let added = false;
      for (const key of pool.sort((x, y) => (UNITS[x].comp === 'core' ? 0 : 1) - (UNITS[y].comp === 'core' ? 0 : 1))) {
        const d = UNITS[key];
        for (let n = Math.min(d.max || 20, 40); n >= (d.min || 1); n--) { const o = { type: key, models: n }; const trial = [...A, o]; if (ok(trial)) { A.push(o); added = true; break; } }
        if (added) break;
      }
      if (!added) break;
    }
    PRESETS[f][2000] = A;
  }
})();

