  const LL = (l) => [LORES[l].sig, ...LORES[l].pool];
  for (const [f, l] of Object.entries(FL)) for (const d of Object.values(UNITS)) if (d.faction === f && d.wizard) d.legacyLore = LL(l);
  const DM = { dm_herald_nurgle: 'dm_nurgle', dm_herald_nurgle_pal: 'dm_nurgle', dm_gud: 'dm_nurgle', dm_herald_tzeentch: 'dm_tzeentch', dm_herald_tzeentch_disc: 'dm_tzeentch', dm_herald_tzeentch_chariot: 'dm_tzeentch', dm_lordchange: 'dm_tzeentch', dm_burningchariot: 'dm_tzeentch', dm_keeper: 'dm_slaanesh' };
  for (const [id, l] of Object.entries(DM)) { const d = UNITS[id]; if (d && d.wizard) d.legacyLore = LL(l); }
  // Heraldo de Slaanesh: sin magia por defecto (85); opcional Nivel 1 (+30) o Nivel 2 (+60); corcel +16
  UNITS.dm_herald_slaanesh.blurb = 'Heraldo seductor: Golpear primero. Sin magia (variantes de mago de Nivel 1/2 aparte).';
