// Listas recomendadas: se reparan las que incumplan la composición oficial (límite de puntos, mínimo de Básicas, tropas, General…)
{
  const cost = (e) => unitCost(e.type, e.models, e.std, e.mus, e.champ, e.items, e.banner, e.arrows, e.mark, e.mix, e.opts);
  const stepOf = (d) => (d.max === 1 || d.cat === 'cav' ? 1 : 5);
  const issuesOf = (A, limit) => armyIssues(A, limit, 'open', 'grand');
  const repair = (army, limit, f) => {
    const A = army.map((e) => ({ ...e }));
    const tot = () => A.reduce((t, e) => t + cost(e), 0);
    const shrink = () => { // reduce la unidad de tropa más cara que admita menos modelos; si no, retira la más cara
      const c = A.filter((e) => e.models && UNITS[e.type].cat !== 'char').sort((a, b) => cost(b) - cost(a));
      for (const e of c) { const d = UNITS[e.type], st = stepOf(d); if (e.models - st >= d.min) { e.models -= st; return true; } }
      if (c.length) { A.splice(A.indexOf(c[0]), 1); return true; } return false;
    };
    for (let it = 0; it < 200; it++) {
      const is = issuesOf(A, limit);
      if (!is.length) return A;
      const t = tot();
      if (is.some((x) => /supera el límite/.test(x))) { if (!shrinkNonCore(A) && !shrink()) return A; continue; }
      if (is.some((x) => /Necesitas un General/.test(x))) {
        const g = Object.values(UNITS).filter((u) => u.faction === f && u.general && u.cat === 'char').sort((a, b) => a.ppm - b.ppm)[0];
        if (!g) return A; A.unshift({ type: g.id, models: 1 }); continue;
      }
      if (is.some((x) => /Mínimo 3 unidades/.test(x))) {
        const c = Object.values(UNITS).filter((u) => u.faction === f && u.comp === 'core' && u.cat !== 'char' && u.cat !== 'mach' && !A.some((e) => e.type === u.id)).sort((a, b) => a.ppm * a.min - b.ppm * b.min)[0];
        if (!c) return A; A.push({ type: c.id, models: c.min });
        let g = 0; while (tot() > limit && g++ < 20) { if (!shrinkNonCore(A, c.id)) return A; } continue;
      }
      if (is.some((x) => /Unidades básicas/.test(x))) {
        const core = A.filter((e) => e.models && UNITS[e.type].comp === 'core' && UNITS[e.type].max > 1).sort((a, b) => cost(a) / a.models - cost(b) / b.models);
        let grown = false;
        for (const e of core) { const d = UNITS[e.type], st = stepOf(d); if (e.models + st <= d.max) { e.models += st; grown = true; break; } }
        if (!grown) { const c = core.length ? UNITS[core[0].type] : null; if (!c) return A; A.push({ type: c.id, models: c.min }); }
        let g = 0; while (tot() > limit && g++ < 20) { if (!shrinkNonCore(A, undefined, false)) return A; } continue;
      }
      const ex = is.find((x) => /0-1|máximo|solo/i.test(x));
      if (ex) {
        let best = -1, bc = 1e9;
        A.forEach((e, i) => { const B = A.filter((_, j) => j !== i); if (!issuesOf(B, limit).includes(ex) && cost(e) < bc) { bc = cost(e); best = i; } });
        if (best < 0) return A; A.splice(best, 1); continue;
      }
      return A;
    }
    return A;
  };
  const shrinkNonCore = (A, keep, allowCore = true) => {
    const c = A.filter((e) => e.models && e.type !== keep && UNITS[e.type].comp !== 'core' && UNITS[e.type].cat !== 'char').sort((a, b) => cost(b) - cost(a));
    for (const e of c) { const d = UNITS[e.type], st = stepOf(d); if (e.models - st >= d.min) { e.models -= st; return true; } }
    const k2 = !allowCore ? [] : A.filter((e) => e.models && e.type !== keep && UNITS[e.type].comp === 'core' && UNITS[e.type].cat !== 'char').sort((a, b) => cost(b) - cost(a));
    for (const e of k2) { const d = UNITS[e.type], st = stepOf(d); if (e.models - st >= d.min) { e.models -= st; return true; } }
    if (c.length) { A.splice(A.indexOf(c[0]), 1); return true; } return false;
  };
  for (const f of Object.keys(PRESETS)) for (const l of Object.keys(PRESETS[f])) {
    if (!issuesOf(PRESETS[f][l], +l).length) continue;
    const r = repair(PRESETS[f][l], +l, f);
    if (!issuesOf(r, +l).length) PRESETS[f][l] = r;
  }
}
