  // Opciones de equipo
  const AHW4 = { id: 'ahw', label: 'Arma de mano adicional', cost: 4, patch: { melee: { extra: 1 } } };
  for (const k of ['ok_butcher', 'ok_butcher_cauldron', 'ok_slaughtermaster', 'ok_slaughter_cauldron']) UNITS[k].opts = [...(UNITS[k].opts || []).filter((o) => o.id !== 'ahw'), AHW4];
  UNITS.ok_firebelly.opts = [...(UNITS.ok_firebelly.opts || []).filter((o) => o.id !== 'gw'), { id: 'gw', label: 'Arma a dos manos', cost: 6, patch: { melee: { sb: 2, ap: 2, ab: 1, twoHands: true, last: true } } }];
