  for (const k of ['ok_tyrant', 'ok_bruiser']) for (const o of UNITS[k].opts) if (o.id === 'pb') o.patch = { ranged: { ...PB }, melee: { extra: 1 } };
  for (const o of UNITS.ok_maneaters.opts) if (o.id === 'bp') { o.patch = { ranged: { ...PB }, melee: { extra: 1 } }; o.group = 'p'; }
  // Devoradores: Tropa variopinta, 0-2 reglas gratuitas, vigía gnoblar; Ogros / Panzahierro: vigía gnoblar
  UNITS.ok_maneaters.sr = [...new Set([...UNITS.ok_maneaters.sr, 'motley'])];
