// Battle March: cualquier personaje puede ser el General (el motor liga «general» al tipo de unidad: se crea una variante idéntica con esa marca)
export function generalType(type) {
  const g = type + '_gen', b = UNITS[type];
  if (!b || b.general) return type;
  if (!UNITS[g]) { UNITS[g] = { ...b, id: g, general: true, name: b.name + ' (General)' }; delete UNITS[g].legacy; FIG_ALIAS[g] = FIG_ALIAS[type] || type; if (CMD[type]) CMD[g] = CMD[type]; }
  return g;
}
