    const sup = armyIssues(a, limit, 'bm', lst || 'grand').filter((z) => /supera el (25|30|35) %/.test(z)); if (!sup.length) break;
    const ix = a.findIndex((e) => e.models && sup.some((z) => z.includes(UNITS[e.type].name + ' supera')));
    if (ix < 0) break; const e = a[ix], d = UNITS[e.type], before = new Set(armyIssues(a, limit, 'bm', lst || 'grand'));
