      const c = Object.values(UNITS).filter((u) => u.faction === d.faction && u.cat === 'char' && u.id !== e.type && !/_(general|gen)$/.test(u.id)).map((u) => ({ id: u.id, c: cost({ type: u.id, models: u.min || 1 }) })).filter((x) => x.c <= limit * 0.25).sort((p, q) => q.c - p.c);
