  SET('vc_ghoulking_terror', { riderA: 5, melee: { ap: 1, maw: { ap: 2, ab: 1, mw: '2', slot: true } }, slots: [NS({ n: 1, maw: true, ws: 3, S: 5, I: 3, apA: 2, abX: 1, mw: 2 }), NS({ n: 3, mawPlus: true, ws: 3, S: 5, I: 3, apA: 1, abX: 1, poison: true }), { n: 'rest', poison: true }] });
  // Nigromante / Acólito en Motor Mortis: jinete con su perfil + 3 Banshees (HA3 F3 I3 A1) + Horda espectral (HA3 F3 I1, D6 Ataques aleatorios)
  for (const k of ['vc_necro_mortis', 'vc_acolyte_mortis']) SET(k, { riderA: UNITS[k] ? UNITS[k].A : 0, slots: [NS({ n: 3, ws: 3, S: 3, I: 3 }), NS({ xRand: true, ws: 3, S: 3, I: 1 }), { n: 'rest' }] });
  // Carro del Caudillo (Chrace): Auriga (HA5 F4 I4 A1, gran hoja: F+2 PA−3, Golpea el último) + 2 Leones Chracios (HA5 F4 I4 A2, Perforante (1) solo de los Leones)
  for (const k of ['he_chieftain_chariot', 'he_korhil_chariot']) SET(k, { slots: [NS({ n: 4, ws: 5, S: 4, I: 4, abX: 1 }), NS({ n: 1, ws: 5, S: 6, I: 4, apA: 3, last: true }), { n: 'rest' }] });
  // Hermanas de la Espina: Corcel de Isha (HA3 F4 I4 A1), FoF p.96
  SET('we_sisters', { A: 2, mountAtk: { a: 1, S: 4, ap: 0, ws: 3, i: 4 } });
